const NL = String.fromCharCode(10);
const inputData = $input.first().json || {};
const isManualTest =
  Object.keys(inputData).length === 0 ||
  (!inputData.body && !inputData.secret_key && !inputData.id_rapat && !inputData.agenda);

const root = inputData.body || inputData || {};
const expectedSecret = '<GANTI_TRANSKEP_WEBHOOK_KEY>';
const defaultCallbackUrl = 'https://script.google.com/macros/s/<GANTI_GAS_DEPLOYMENT_ID>/exec';
const incomingSecret = String(root.secret_key || '').trim();
const isAuthorized = isManualTest || (incomingSecret !== '' && incomingSecret === expectedSecret);

const idRapat = String(root.id_rapat || (isManualTest ? 'RPT-TEST-001' : '')).trim();
const agenda = String(root.agenda || (isManualTest ? 'Rapat Koordinasi Bulanan & Evaluasi Kinerja' : 'Rapat Kedinasan')).trim();
const hariTanggal = String(root.hari_tanggal || 'Rabu, 18 November 2026').trim();
const tempat = String(root.tempat || 'Ruang Rapat Pimpinan Pengadilan Agama Indramayu').trim();
const pemimpin = String(root.pemimpin || 'Ketua Pengadilan Agama Indramayu').trim();
const notulis = String(root.notulis || 'Notulis Rapat').trim();

let pesertaList = [];
try {
  if (Array.isArray(root.peserta_list)) pesertaList = root.peserta_list;
  else if (typeof root.peserta_list === 'string' && root.peserta_list.trim()) {
    pesertaList = JSON.parse(root.peserta_list);
  }
} catch (e) {
  pesertaList = [];
}

const transcriptText = String(
  root.transcript_text ||
    root.ai_transcript ||
    (isManualTest
      ? 'Ketua memberikan pengarahan agar seluruh bagian mempercepat penyelesaian laporan bulanan. Sekretaris melaporkan progres pengadaan dan tindak lanjut pemeliharaan sarana sidang dengan target selesai akhir November 2026.'
      : '')
).trim();

const rawAudio = String(root.audio_base64 || root.audio_data || '').trim();
const cleanAudioBase64 = rawAudio.replace(/^data:audio\/[^;]+;base64,/i, '').replace(/\s+/g, '');
const audioDriveFileId = String(root.audio_drive_file_id || '').trim();
const audioFileName = String(root.audio_file_name || (audioDriveFileId ? 'rekaman_rapat.m4a' : 'rekaman_rapat.webm')).trim();
let audioMimeType = String(root.audio_mime_type || root.mime_type || 'audio/webm').split(';')[0].trim().toLowerCase() || 'audio/webm';
if (audioMimeType === 'audio/x-m4a' || audioMimeType === 'audio/m4a' || (/\.m4a$/i.test(audioFileName) && (!audioMimeType || audioMimeType === 'video/mp4'))) {
  audioMimeType = 'audio/mp4';
}
const audioSizeBytes = parseInt(root.audio_size_bytes || '0', 10) || 0;
const jobId = String(root.job_id || '').trim();
const callbackUrl = String(root.callback_url || defaultCallbackUrl).trim() || defaultCallbackUrl;
const isAsyncDriveAudio = Boolean(audioDriveFileId && jobId && !cleanAudioBase64);

const pesertaInfoLines = Array.isArray(pesertaList)
  ? pesertaList
      .slice(0, 50)
      .map((p, idx) => {
        if (typeof p === 'string') return idx + 1 + '. ' + p;
        return (
          idx +
          1 +
          '. ' +
          String(p.nama || p.label || '-') +
          (p.jabatan ? ' (' + p.jabatan + ')' : '') +
          (p.nip ? ' [NIP: ' + p.nip + ']' : '')
        );
      })
      .join(NL)
  : '';

const fullSystemPrompt =
  'Kamu adalah Transkep AI, Notulis Eksekutif resmi Pengadilan Agama Indramayu (Mahkamah Agung RI).' +
  NL +
  'Tugasmu menganalisis rekaman audio rapat dan/atau catatan mentah rapat menjadi JSON Notula Rapat Kedinasan terstruktur sesuai tata naskah dinas peradilan.' +
  NL +
  'KELUARAN WAJIB HANYA JSON MURNI (tanpa teks pembuka/penutup) dengan skema persis berikut:' +
  NL +
  '{' +
  NL +
  '  "dasar_opsional": "string dasar pelaksanaan rapat jika disebut di audio/catatan, atau string kosong",' +
  NL +
  '  "pengarahan_umum": "ringkasan pengarahan umum pimpinan rapat yang rapi & formal",' +
  NL +
  '  "kesimpulan": "kesimpulan/keputusan akhir rapat secara ringkas",' +
  NL +
  '  "transkrip_ringkas": "ringkasan alur pembicaraan / transkrip bersih rapat",' +
  NL +
  '  "pembahasan": [' +
  NL +
  '    {' +
  NL +
  '      "pembicara_nama": "Nama & Jabatan Pembicara (cocokkan dengan daftar peserta bila tersedia)",' +
  NL +
  '      "pembicara_nip": "NIP pembicara jika ditemukan di daftar peserta, atau kosong",' +
  NL +
  '      "pembicara_jabatan": "Jabatan pembicara",' +
  NL +
  '      "uraian": ["Poin 1 uraian/laporan", "Poin 2 uraian/laporan"],' +
  NL +
  '      "tindak_lanjut": ["Poin 1 tindak lanjut/tanggapan", "Poin 2 tindak lanjut"],' +
  NL +
  '      "target": "Target penyelesaian output yang terukur",' +
  NL +
  '      "penanggung_jawab": "Pihak / jabatan penanggung jawab",' +
  NL +
  '      "tanggal_penyelesaian": "Batas waktu / tanggal penyelesaian jika disebut, atau Segera / -"' +
  NL +
  '    }' +
  NL +
  '  ]' +
  NL +
  '}';

const hasAudioInput = Boolean(cleanAudioBase64 || isAsyncDriveAudio);
const cleanPrompt =
  '=== IDENTITAS RAPAT KEDINASAN PA INDRAMAYU ===' +
  NL +
  'ID Rapat: ' +
  (idRapat || '-') +
  NL +
  'Agenda / Acara: ' +
  agenda +
  NL +
  'Hari / Tanggal: ' +
  hariTanggal +
  NL +
  'Tempat: ' +
  tempat +
  NL +
  'Pimpinan Rapat: ' +
  pemimpin +
  NL +
  'Notulis: ' +
  notulis +
  NL +
  (pesertaInfoLines ? NL + 'Daftar Peserta Terdaftar:' + NL + pesertaInfoLines + NL : '') +
  (transcriptText ? NL + 'Catatan Mentah / Konteks Tambahan:' + NL + transcriptText + NL : '') +
  NL +
  (hasAudioInput
    ? 'Dengarkan rekaman audio rapat terlampir secara cermat, identifikasi pembicara, dan susun ke dalam JSON skema notula 5 kolom (Uraian, Tindak Lanjut, Target, Penanggung Jawab, Tanggal Penyelesaian).'
    : 'Susun catatan rapat di atas menjadi JSON skema notula 5 kolom (Uraian, Tindak Lanjut, Target, Penanggung Jawab, Tanggal Penyelesaian) dalam Bahasa Indonesia kedinasan yang baku.');

const parts = [];
if (cleanAudioBase64) {
  parts.push({
    inline_data: {
      mime_type: audioMimeType,
      data: cleanAudioBase64,
    },
  });
}
parts.push({ text: cleanPrompt });

const geminiRequestBody = {
  system_instruction: {
    parts: [{ text: fullSystemPrompt }],
  },
  contents: [
    {
      role: 'user',
      parts,
    },
  ],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
  },
};

return [
  {
    json: {
      isAuthorized,
      isManualTest,
      isAsyncDriveAudio,
      job_id: jobId,
      callback_url: callbackUrl,
      secret_key: expectedSecret,
      id_rapat: idRapat,
      agenda,
      audioAttached: hasAudioInput,
      audio_drive_file_id: audioDriveFileId,
      audioFileName,
      audioMimeType,
      audioSizeBytes,
      cleanPrompt,
      fullSystemPrompt,
      geminiRequestBody,
    },
  },
];

const NL = String.fromCharCode(10);
const ctx = $('Validasi & Siapkan Prompt Notulen (Code)').first().json || {};
const item = $input.first().json || {};

if (item.error) {
  const errMsg = String(item.error.message || item.error || 'Gemini API gagal merespons.');
  return [
    {
      json: {
        status: 'error',
        id_rapat: String(ctx.id_rapat || ''),
        model: 'models/gemini-3.8-flash',
        message: 'Kendala Gemini Multimodal API: ' + errMsg,
      },
    },
  ];
}

let rawText = '';
try {
  if (
    item.candidates &&
    item.candidates[0] &&
    item.candidates[0].content &&
    Array.isArray(item.candidates[0].content.parts) &&
    item.candidates[0].content.parts[0]
  ) {
    rawText = String(item.candidates[0].content.parts[0].text || '');
  } else {
    rawText = String(item.output || item.text || '');
  }
} catch (e) {
  rawText = '';
}

const cleanedJsonStr = rawText
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed = null;
try {
  if (cleanedJsonStr.startsWith('{') || cleanedJsonStr.startsWith('[')) {
    parsed = JSON.parse(cleanedJsonStr);
  } else if (typeof item.pengarahan_umum === 'string' || Array.isArray(item.pembahasan)) {
    parsed = item;
  }
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return [
    {
      json: {
        status: 'error',
        id_rapat: String(ctx.id_rapat || ''),
        model: 'models/gemini-3.8-flash',
        message: 'Output Gemini tidak berbentuk JSON valid.',
        raw_preview: cleanedJsonStr.slice(0, 500),
      },
    },
  ];
}

function toList(val) {
  if (Array.isArray(val)) {
    return val.map((x) => String(x == null ? '' : x).trim()).filter(Boolean);
  }
  const s = String(val == null ? '' : val).trim();
  if (!s) return [];
  return s
    .split(/\r?\n/)
    .map((line) => line.replace(/^\s*[-*•\d.)]+\s*/, '').trim())
    .filter(Boolean);
}

function toNumberedText(list) {
  if (!Array.isArray(list) || list.length === 0) return '';
  if (list.length === 1) return list[0];
  return list.map((line, i) => i + 1 + '. ' + line).join(NL);
}

const rawRows = Array.isArray(parsed.pembahasan) ? parsed.pembahasan : [];
const pembahasan = rawRows.slice(0, 30).map((r, idx) => {
  const row = r && typeof r === 'object' ? r : {};
  const uraianList = toList(row.uraian);
  const tindakList = toList(row.tindak_lanjut);
  return {
    pembicara_nama: String(row.pembicara_nama || row.pembicara || 'Pembicara #' + (idx + 1)).trim(),
    pembicara_nip: String(row.pembicara_nip || '').trim(),
    pembicara_jabatan: String(row.pembicara_jabatan || '').trim(),
    uraian: uraianList,
    uraian_text: toNumberedText(uraianList),
    tindak_lanjut: tindakList,
    tindak_lanjut_text: toNumberedText(tindakList),
    target: String(row.target || '').trim(),
    penanggung_jawab: String(row.penanggung_jawab || '').trim(),
    tanggal_penyelesaian: String(row.tanggal_penyelesaian || '').trim(),
  };
});

return [
  {
    json: {
      status: 'success',
      id_rapat: String(ctx.id_rapat || ''),
      model: 'models/gemini-3.8-flash',
      data: {
        dasar_opsional: String(parsed.dasar_opsional || '').trim(),
        pengarahan_umum: String(parsed.pengarahan_umum || '').trim(),
        kesimpulan: String(parsed.kesimpulan || '').trim(),
        transkrip_ringkas: String(parsed.transkrip_ringkas || '').trim(),
        pembahasan,
      },
    },
  },
];

const ctx = $('Validasi & Siapkan Prompt Notulen (Code)').first().json || {};
const startRes = $('Start Gemini Files Resumable Session (HTTP)').first().json || {};
const dlRes = $('Download Audio dari Google Drive').first().json || {};
const upRes = $input.first().json || {};

let errMsg = '';
if (startRes.error) {
  errMsg = 'Gagal memulai sesi Gemini Files API: ' + String(startRes.error.message || startRes.error);
} else if (startRes.statusCode && Number(startRes.statusCode) >= 400) {
  errMsg = 'Gemini Files API menolak sesi upload (HTTP ' + startRes.statusCode + ').';
} else if (dlRes.error) {
  errMsg = 'Gagal mengunduh audio dari Google Drive (Service Account): ' + String(dlRes.error.message || dlRes.error);
} else if (upRes.error) {
  errMsg = 'Gagal mengunggah binary audio ke Gemini Files API: ' + String(upRes.error.message || upRes.error);
}

let parsedBody = upRes;
if (typeof upRes.body === 'string' && upRes.body.trim().startsWith('{')) {
  try { parsedBody = JSON.parse(upRes.body); } catch (eP) {}
} else if (upRes.body && typeof upRes.body === 'object') {
  parsedBody = upRes.body;
}

const fileObj = (parsedBody && parsedBody.file && typeof parsedBody.file === 'object') ? parsedBody.file : (parsedBody || {});
const fileName = String(fileObj.name || '').trim();
const fileUri = String(fileObj.uri || '').trim();
const fileState = String(fileObj.state || (fileUri ? 'ACTIVE' : '')).trim().toUpperCase();
const fileMime = String(fileObj.mimeType || ctx.audioMimeType || 'audio/mp4').trim();

if (!errMsg && !fileUri) {
  errMsg = 'Gemini Files API tidak mengembalikan file.uri setelah upload.';
}

return [
  {
    json: {
      uploadOk: Boolean(fileUri && !errMsg),
      errorMessage: errMsg,
      fileName,
      fileUri,
      fileState,
      fileMime,
      pollCount: 0,
      pollFailedMessage: '',
    },
  },
];

const prev = $('Cek Upload & Siapkan Gemini FileURI (Code)').first().json || {};
const statusRes = $input.first().json || {};
let waitCount = 1;
try {
  waitCount = $('Tunggu Proses File Gemini 5 Detik (Wait)').all().length;
} catch (eW) {
  waitCount = 1;
}

if (statusRes.error) {
  return [
    {
      json: {
        ...prev,
        fileState: 'ACTIVE',
        pollCount: waitCount,
        pollFailedMessage: 'Gagal mengecek status file Gemini: ' + String(statusRes.error.message || statusRes.error),
      },
    },
  ];
}

const f = (statusRes.file && typeof statusRes.file === 'object') ? statusRes.file : statusRes;
const st = String(f.state || 'PROCESSING').trim().toUpperCase();

if (st === 'FAILED') {
  return [
    {
      json: {
        ...prev,
        fileState: 'ACTIVE',
        pollCount: waitCount,
        pollFailedMessage: 'Pemrosesan audio oleh Gemini Files API gagal (state: FAILED).',
      },
    },
  ];
}

if (st === 'ACTIVE') {
  return [
    {
      json: {
        ...prev,
        fileName: String(f.name || prev.fileName || ''),
        fileUri: String(f.uri || prev.fileUri || ''),
        fileMime: String(f.mimeType || prev.fileMime || 'audio/mp4'),
        fileState: 'ACTIVE',
        pollCount: waitCount,
        pollFailedMessage: '',
      },
    },
  ];
}

if (waitCount >= 24) {
  return [
    {
      json: {
        ...prev,
        fileState: 'ACTIVE',
        pollCount: waitCount,
        pollFailedMessage: 'Timeout menunggu file audio Gemini ACTIVE (> 120 detik).',
      },
    },
  ];
}

return [
  {
    json: {
      ...prev,
      fileState: st || 'PROCESSING',
      pollCount: waitCount,
      pollFailedMessage: '',
    },
  },
];

const ctx = $('Validasi & Siapkan Prompt Notulen (Code)').first().json || {};
const cur = $input.first().json || {};

const geminiRequestBody = {
  system_instruction: {
    parts: [{ text: ctx.fullSystemPrompt }],
  },
  contents: [
    {
      role: 'user',
      parts: [
        {
          file_data: {
            mime_type: cur.fileMime || ctx.audioMimeType || 'audio/mp4',
            file_uri: cur.fileUri,
          },
        },
        {
          text: ctx.cleanPrompt,
        },
      ],
    },
  ],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
  },
};

return [
  {
    json: {
      fileName: cur.fileName || '',
      fileUri: cur.fileUri || '',
      pollFailedMessage: cur.pollFailedMessage || '',
      geminiRequestBody,
    },
  },
];

const NL = String.fromCharCode(10);
const ctx = $('Validasi & Siapkan Prompt Notulen (Code)').first().json || {};
const fileCtx = $('Siapkan Payload Gemini FileURI (Code)').first().json || {};
const item = $input.first().json || {};

const baseMeta = {
  action: 'callbackAiNotulenJob',
  secret_key: String(ctx.secret_key || ''),
  job_id: String(ctx.job_id || ''),
  id_rapat: String(ctx.id_rapat || ''),
  model: 'models/gemini-3.8-flash',
};

if (fileCtx.pollFailedMessage) {
  return [
    {
      json: {
        callbackUrl: ctx.callback_url,
        geminiFileName: String(fileCtx.fileName || ''),
        callbackPayload: {
          ...baseMeta,
          status: 'error',
          message: String(fileCtx.pollFailedMessage),
        },
      },
    },
  ];
}

if (item.error) {
  const errMsg = String(item.error.message || item.error || 'Gemini API gagal merespons.');
  return [
    {
      json: {
        callbackUrl: ctx.callback_url,
        geminiFileName: String(fileCtx.fileName || ''),
        callbackPayload: {
          ...baseMeta,
          status: 'error',
          message: 'Kendala Gemini FileURI API: ' + errMsg,
        },
      },
    },
  ];
}

let rawText = '';
try {
  if (
    item.candidates &&
    item.candidates[0] &&
    item.candidates[0].content &&
    Array.isArray(item.candidates[0].content.parts) &&
    item.candidates[0].content.parts[0]
  ) {
    rawText = String(item.candidates[0].content.parts[0].text || '');
  } else {
    rawText = String(item.output || item.text || '');
  }
} catch (e) {
  rawText = '';
}

const cleanedJsonStr = rawText
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed = null;
try {
  if (cleanedJsonStr.startsWith('{') || cleanedJsonStr.startsWith('[')) {
    parsed = JSON.parse(cleanedJsonStr);
  } else if (typeof item.pengarahan_umum === 'string' || Array.isArray(item.pembahasan)) {
    parsed = item;
  }
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return [
    {
      json: {
        callbackUrl: ctx.callback_url,
        geminiFileName: String(fileCtx.fileName || ''),
        callbackPayload: {
          ...baseMeta,
          status: 'error',
          message: 'Output Gemini FileURI tidak berbentuk JSON valid.',
        },
      },
    },
  ];
}

function toList(val) {
  if (Array.isArray(val)) {
    return val.map((x) => String(x == null ? '' : x).trim()).filter(Boolean);
  }
  const s = String(val == null ? '' : val).trim();
  if (!s) return [];
  return s
    .split(/\r?\n/)
    .map((line) => line.replace(/^\s*[-*•\d.)]+\s*/, '').trim())
    .filter(Boolean);
}

function toNumberedText(list) {
  if (!Array.isArray(list) || list.length === 0) return '';
  if (list.length === 1) return list[0];
  return list.map((line, i) => i + 1 + '. ' + line).join(NL);
}

const rawRows = Array.isArray(parsed.pembahasan) ? parsed.pembahasan : [];
const pembahasan = rawRows.slice(0, 30).map((r, idx) => {
  const row = r && typeof r === 'object' ? r : {};
  const uraianList = toList(row.uraian);
  const tindakList = toList(row.tindak_lanjut);
  return {
    pembicara_nama: String(row.pembicara_nama || row.pembicara || 'Pembicara #' + (idx + 1)).trim(),
    pembicara_nip: String(row.pembicara_nip || '').trim(),
    pembicara_jabatan: String(row.pembicara_jabatan || '').trim(),
    uraian: uraianList,
    uraian_text: toNumberedText(uraianList),
    tindak_lanjut: tindakList,
    tindak_lanjut_text: toNumberedText(tindakList),
    target: String(row.target || '').trim(),
    penanggung_jawab: String(row.penanggung_jawab || '').trim(),
    tanggal_penyelesaian: String(row.tanggal_penyelesaian || '').trim(),
  };
});

return [
  {
    json: {
      callbackUrl: ctx.callback_url,
      geminiFileName: String(fileCtx.fileName || ''),
      callbackPayload: {
        ...baseMeta,
        status: 'success',
        data: {
          dasar_opsional: String(parsed.dasar_opsional || '').trim(),
          pengarahan_umum: String(parsed.pengarahan_umum || '').trim(),
          kesimpulan: String(parsed.kesimpulan || '').trim(),
          transkrip_ringkas: String(parsed.transkrip_ringkas || '').trim(),
          pembahasan,
        },
      },
    },
  },
];

const ctx = $('Validasi & Siapkan Prompt Notulen (Code)').first().json || {};
const upInfo = $input.first().json || {};

return [
  {
    json: {
      callbackUrl: ctx.callback_url,
      geminiFileName: String(upInfo.fileName || ''),
      callbackPayload: {
        action: 'callbackAiNotulenJob',
        secret_key: String(ctx.secret_key || ''),
        job_id: String(ctx.job_id || ''),
        id_rapat: String(ctx.id_rapat || ''),
        status: 'error',
        message: String(upInfo.errorMessage || 'Gagal mengunggah audio rapat ke Gemini Files API.'),
      },
    },
  },
];
